"""Environment-factor construction and local EvalAwareBench-style ingestion."""

from __future__ import annotations

import csv
import json
from collections.abc import Iterable, Mapping
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

from ..schemas import EnvironmentFactor, ValidationError

FactorValue = str | bool | int | float

# These names collapsed a measured recognition target and an observed behavior in
# early data files.  Silently accepting them would make the two endpoints
# scientifically indistinguishable.
LEGACY_ALIASES = frozenset(
    {
        "label",
        "outcome",
        "evaluation_label",
        "eval_awareness_label",
        "recognition_outcome",
    }
)


def factor_vector(factors: Mapping[str, FactorValue]) -> tuple[EnvironmentFactor, ...]:
    """Return a canonical vector whose dimensions can be changed independently."""

    if not factors:
        raise ValidationError("environment factor vector must not be empty")
    vector: list[EnvironmentFactor] = []
    for name, value in sorted(factors.items()):
        if not isinstance(name, str) or not name.strip():
            raise ValidationError("environment factor names must be non-empty strings")
        if name in LEGACY_ALIASES:
            raise ValidationError(f"legacy aliased field is prohibited: {name}")
        if isinstance(value, (dict, list, tuple)) or value is None:
            raise ValidationError(f"invalid value for environment factor {name!r}")
        vector.append(EnvironmentFactor(name=name, value=value))
    return tuple(vector)


def set_factor(
    factors: Iterable[EnvironmentFactor], name: str, value: FactorValue
) -> tuple[EnvironmentFactor, ...]:
    """Set exactly one factor, preserving every other factor dimension."""

    current = {factor.name: factor.value for factor in factors}
    current[name] = value
    return factor_vector(current)


def _require_local_data_path(path: str | Path) -> Path:
    text = str(path)
    parsed = urlparse(text)
    if parsed.scheme or parsed.netloc:
        raise ValidationError("adapter accepts a caller-supplied local path only")
    local = Path(path)
    if not local.is_file():
        raise ValidationError(f"local dataset path does not exist or is not a file: {local}")
    if local.suffix.lower() not in {".jsonl", ".csv"}:
        raise ValidationError("adapter supports only local .jsonl and .csv files")
    return local


def _decode_csv_cell(value: str) -> Any:
    stripped = value.strip()
    if not stripped:
        return ""
    if stripped[0] in "[{\"" or stripped in {"true", "false", "null"}:
        try:
            return json.loads(stripped)
        except json.JSONDecodeError:
            return value
    return value


def _validate_adapter_row(row: Mapping[str, Any], line_number: int) -> dict[str, Any]:
    prohibited = LEGACY_ALIASES.intersection(row)
    if prohibited:
        names = ", ".join(sorted(prohibited))
        raise ValidationError(f"row {line_number} uses prohibited legacy alias(es): {names}")
    if "recognition_label" not in row and "behavioral_outcome" not in row:
        raise ValidationError(
            f"row {line_number} must declare recognition_label and/or behavioral_outcome explicitly"
        )
    result = dict(row)
    raw_factors = result.get("environment_factors")
    if raw_factors is None:
        prefixed = {
            key.removeprefix("factor_"): value
            for key, value in result.items()
            if key.startswith("factor_")
        }
        if prefixed:
            raw_factors = prefixed
    if raw_factors is not None:
        if not isinstance(raw_factors, Mapping):
            raise ValidationError(f"row {line_number} environment_factors must be an object")
        result["environment_factors"] = {
            item.name: item.value for item in factor_vector(raw_factors)
        }
    return result


def load_evalawarebench(path: str | Path) -> list[dict[str, Any]]:
    """Load an EvalAwareBench-style file without downloads or implicit discovery.

    The adapter deliberately takes only a local JSONL/CSV path.  Endpoint fields
    retain their explicit ``recognition_label`` and ``behavioral_outcome`` names.
    """

    local = _require_local_data_path(path)
    rows: list[dict[str, Any]] = []
    if local.suffix.lower() == ".jsonl":
        with local.open(encoding="utf-8") as handle:
            for line_number, line in enumerate(handle, 1):
                if not line.strip():
                    continue
                try:
                    value = json.loads(line)
                except json.JSONDecodeError as error:
                    raise ValidationError(f"invalid JSON on line {line_number}: {error.msg}") from error
                if not isinstance(value, Mapping):
                    raise ValidationError(f"row {line_number} must be a JSON object")
                rows.append(_validate_adapter_row(value, line_number))
    else:
        with local.open(encoding="utf-8", newline="") as handle:
            reader = csv.DictReader(handle)
            if reader.fieldnames is None:
                raise ValidationError("CSV file must include a header")
            for line_number, row in enumerate(reader, 2):
                decoded = {key: _decode_csv_cell(value) for key, value in row.items()}
                rows.append(_validate_adapter_row(decoded, line_number))
    if not rows:
        raise ValidationError("dataset contains no rows")
    return rows


class EvalAwareBenchAdapter:
    """Namespace adapter for explicit local EvalAwareBench-style files."""

    @staticmethod
    def load(path: str | Path) -> list[dict[str, Any]]:
        return load_evalawarebench(path)

"""Leakage-resistant deterministic grouped data splitting."""

from __future__ import annotations

import hashlib
from collections import defaultdict
from collections.abc import Iterable, Mapping
from dataclasses import dataclass, replace
from typing import TypeVar

from ..schemas import PromptRecord, Split, ValidationError

_DEFAULT_PROPORTIONS: Mapping[Split, float] = {
    Split.TRAIN: 0.7,
    Split.VALIDATION: 0.1,
    Split.TEST: 0.1,
    Split.CONFIRMATION: 0.1,
}


def _stable_order(value: str, seed: int) -> bytes:
    return hashlib.sha256(f"{seed}\0{value}".encode()).digest()


def validate_split_integrity(records: Iterable[PromptRecord]) -> None:
    """Raise on duplicate rows, source-task leakage, or confirmation-family leakage."""

    materialized = list(records)
    row_ids: set[str] = set()
    source_splits: dict[str, set[Split]] = defaultdict(set)
    family_splits: dict[str, set[Split]] = defaultdict(set)
    for record in materialized:
        if record.row_id in row_ids:
            raise ValidationError(f"repeated prompt variant row_id: {record.row_id}")
        row_ids.add(record.row_id)
        source_splits[record.source_task_id].add(record.split)
        family_splits[record.template_family].add(record.split)
    leaked_sources = sorted(source for source, splits in source_splits.items() if len(splits) > 1)
    if leaked_sources:
        raise ValidationError(f"source_task_id leakage across splits: {leaked_sources}")
    leaked_families = sorted(
        family
        for family, splits in family_splits.items()
        if Split.CONFIRMATION in splits and len(splits) > 1
    )
    if leaked_families:
        raise ValidationError(
            f"template-family leakage into confirmation: {leaked_families}"
        )


class _DisjointSet:
    def __init__(self, values: Iterable[str]) -> None:
        self.parent = {value: value for value in values}

    def find(self, value: str) -> str:
        parent = self.parent[value]
        if parent != value:
            self.parent[value] = self.find(parent)
        return self.parent[value]

    def union(self, left: str, right: str) -> None:
        left_root = self.find(left)
        right_root = self.find(right)
        if left_root != right_root:
            self.parent[right_root] = left_root


def assign_grouped_splits(
    records: Iterable[PromptRecord],
    *,
    seed: int = 0,
    proportions: Mapping[Split, float] = _DEFAULT_PROPORTIONS,
) -> list[PromptRecord]:
    """Assign source groups deterministically with confirmation families isolated.

    Connected components of source-task IDs and template families are atomic.
    This is slightly stricter than required, but guarantees that any family
    selected for confirmation is absent from all development splits.
    """

    materialized = list(records)
    if not materialized:
        raise ValidationError("cannot split an empty dataset")
    if len({record.row_id for record in materialized}) != len(materialized):
        raise ValidationError("repeated prompt variant row_id")
    expected = set(Split)
    if set(proportions) != expected or any(value <= 0 for value in proportions.values()):
        raise ValidationError("proportions must give every split a positive weight")
    total_proportion = sum(proportions.values())
    if abs(total_proportion - 1.0) > 1e-9:
        raise ValidationError("split proportions must sum to one")

    source_nodes = {f"source:{record.source_task_id}" for record in materialized}
    family_nodes = {f"family:{record.template_family}" for record in materialized}
    groups = _DisjointSet(source_nodes | family_nodes)
    for record in materialized:
        groups.union(f"source:{record.source_task_id}", f"family:{record.template_family}")

    component_rows: dict[str, list[PromptRecord]] = defaultdict(list)
    for record in materialized:
        component_rows[groups.find(f"source:{record.source_task_id}")].append(record)
    ordered = sorted(component_rows, key=lambda key: _stable_order(key, seed))
    targets = {split: len(materialized) * proportions[split] for split in Split}
    counts = dict.fromkeys(Split, 0)
    component_split: dict[str, Split] = {}
    for index, component in enumerate(ordered):
        # Ensure each split is represented when there are enough independent
        # components, then use the largest normalized deficit.
        if index < len(Split) and len(ordered) >= len(Split):
            chosen = tuple(Split)[index]
        else:
            chosen = max(
                Split,
                key=lambda split: (
                    (targets[split] - counts[split]) / proportions[split],
                    -tuple(Split).index(split),
                ),
            )
        component_split[component] = chosen
        counts[chosen] += len(component_rows[component])

    assigned = [
        replace(record, split=component_split[groups.find(f"source:{record.source_task_id}")])
        for record in materialized
    ]
    validate_split_integrity(assigned)
    return assigned


@dataclass(frozen=True)
class DevelopmentFold:
    """One outer held-out group fold and its nested inner validation folds."""

    outer_index: int
    outer_test_source_task_ids: frozenset[str]
    inner_validation_source_task_ids: tuple[frozenset[str], ...]


def nested_group_development_folds(
    records: Iterable[PromptRecord],
    *,
    outer_folds: int = 5,
    inner_folds: int = 4,
    seed: int = 0,
) -> tuple[DevelopmentFold, ...]:
    """Build deterministic nested folds over non-confirmation source groups."""

    materialized = list(records)
    validate_split_integrity(materialized)
    development_ids = sorted(
        {
            record.source_task_id
            for record in materialized
            if record.split is not Split.CONFIRMATION
        },
        key=lambda value: _stable_order(value, seed),
    )
    if outer_folds < 2 or inner_folds < 2:
        raise ValidationError("nested folds require at least two outer and inner folds")
    if len(development_ids) < outer_folds:
        raise ValidationError("fewer development groups than outer folds")
    outer_buckets = [frozenset(development_ids[index::outer_folds]) for index in range(outer_folds)]
    result: list[DevelopmentFold] = []
    for outer_index, outer_test in enumerate(outer_buckets):
        remaining = [task_id for task_id in development_ids if task_id not in outer_test]
        if len(remaining) < inner_folds:
            raise ValidationError("fewer outer-training groups than inner folds")
        inner_order = sorted(
            remaining,
            key=lambda value: _stable_order(value, seed + outer_index + 1),
        )
        inner = tuple(
            frozenset(inner_order[index::inner_folds]) for index in range(inner_folds)
        )
        result.append(
            DevelopmentFold(
                outer_index=outer_index,
                outer_test_source_task_ids=outer_test,
                inner_validation_source_task_ids=inner,
            )
        )
    return tuple(result)


_Row = TypeVar("_Row", bound=PromptRecord)


def assign_splits(
    records: Iterable[_Row], *, seed: int = 0
) -> list[PromptRecord]:
    """Concise alias for the default grouped split protocol."""

    return assign_grouped_splits(records, seed=seed)

